-- M-03: definitions and implementation contracts; no execution or automatic publication.
ALTER TABLE bm_action ADD COLUMN contract_json JSON NULL;
ALTER TABLE bm_axiom ADD COLUMN enforcement_json JSON NULL;
INSERT INTO bm_action (action_code,name,concept_code,from_status,to_status,trigger_desc,description,status,version,contract_json) SELECT 'COMPUTE_NOTIFY','通知受影响人员','COMPUTE_DEPLOYMENT','RESERVED','NOTIFIED','预留有效；收件人使用稳定编号','撤销预留并补偿','DRAFT','1','{"actionType": "NOTIFY", "guardRules": ["R-05", "R-08"], "preconditions": "预留有效；收件人使用稳定编号", "failureRoute": "撤销预留并补偿", "idempotency": "execution_action.idempotency_key", "resultQuery": "/api/compute/actions/results?operationKey=<idempotency_key>", "executor": "N-11/N-12", "executionEnabled": false}' WHERE NOT EXISTS (SELECT 1 FROM bm_action WHERE action_code='COMPUTE_NOTIFY');
