INSERT INTO bm_action (action_code,name,concept_code,from_status,to_status,trigger_desc,description,status,version,contract_json) SELECT 'COMPUTE_DRAIN','停止接收请求','COMPUTE_DEPLOYMENT','NOTIFIED','DRAINED','通知成功；预留和授权仍有效','核对回执后撤销或补偿','DRAFT','1','{"actionType": "DRAIN", "guardRules": ["R-05"], "preconditions": "通知成功；预留和授权仍有效", "failureRoute": "核对回执后撤销或补偿", "idempotency": "execution_action.idempotency_key", "resultQuery": "/api/compute/actions/results?operationKey=<idempotency_key>", "executor": "N-11/N-12", "executionEnabled": false}' WHERE NOT EXISTS (SELECT 1 FROM bm_action WHERE action_code='COMPUTE_DRAIN');
