INSERT INTO bm_action (action_code,name,concept_code,from_status,to_status,trigger_desc,description,status,version,contract_json) SELECT 'COMPUTE_STOP','停止常驻模型','COMPUTE_DEPLOYMENT','DRAINED','STOPPED','摘流成功；在途请求为零','未确认退出禁止交接','DRAFT','1','{"actionType": "STOP", "guardRules": ["R-05"], "preconditions": "摘流成功；在途请求为零", "failureRoute": "未确认退出禁止交接", "idempotency": "execution_action.idempotency_key", "resultQuery": "/api/compute/actions/results?operationKey=<idempotency_key>", "executor": "N-11/N-12", "executionEnabled": false}' WHERE NOT EXISTS (SELECT 1 FROM bm_action WHERE action_code='COMPUTE_STOP');
