INSERT INTO bm_axiom (axiom_code,subject,predicate,object,axiom_type,description,status,enforcement_json) SELECT 'COMPUTE_I01','COMPUTE_GPU_GROUP','必须满足','同一申请同时最多一个活跃作业','约束','同一申请同时最多一个活跃作业','DRAFT','{"id": "I-1", "enforcement": "DATABASE", "implementation": "active_job.PRIMARY + UNIQUE(job_id)", "verification": "ComputeNormDatabaseTest", "integration": "`active_job` 的唯一性和同事务更新"}' WHERE NOT EXISTS (SELECT 1 FROM bm_axiom WHERE axiom_code='COMPUTE_I01');
